# Build the solution with the simple bottom-stack rule and submit
def compute_simple_output():
    out_grid = [[8] * 18 for _ in range(20)]
    for c in range(18):
        col_in = [input_grid[r][c] for r in range(20)]
        non8s = [v for v in col_in if v != 8]
        if not non8s:
            continue
        for i, v in enumerate(non8s):
            out_grid[19 - i][c] = v
    return out_grid

grid = compute_simple_output()

final_answer = {"action": "submit", "grid": grid}
print(final_answer)

